xql_query:
// ============================================================
// Rule: Endpoint Monitorado Online (Copy)
// Vendor: Cortex
// Objective:
// Detect activity associated with Endpoint Monitorado Online (Copy).
// Severity: SEV_050_CRITICAL
// Category: OTHER
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.

dataset=endpoints
| filter endpoint_name = "<ENDPOINT_NAME>"
| fields endpoint_name, last_seen, endpoint_status 
| filter endpoint_status contains "CONNECTED" and endpoint_status not contains "DISCONNECTED"
